# Verify the BFS path to a few nodes at depth 6 to ensure correctness
def trace_path(node, depths, graph):
    """Trace back the path from a node to start"""
    path = [node]
    current = node
    # Build reverse graph for parent lookup
    reverse_graph = defaultdict(list)
    for src, targets in graph.items():
        for tgt in targets:
            reverse_graph[tgt].append(src)

    while depths.get(current, 0) > 0:
        parents = [p for p in reverse_graph.get(current, []) if depths.get(p, -1) == depths[current] - 1]
        if parents:
            current = parents[0]
            path.append(current)
        else:
            break
    return list(reversed(path))

